import{migrate,PARTNERS,STAGES,EEVEE_FORMS}from'./trainer-engine.mjs?v=4.2';
export function restoreProgress(text,data){
 const raw=JSON.parse(text);if(![2,3].includes(raw.version)||!Array.isArray(raw.records)||!Array.isArray(raw.players)||raw.players.length!==2)throw Error('请选择本游戏导出的进度 JSON');
 const books=new Set(data.books.map(b=>b.id)),ids=new Map(data.words.map(w=>[w.id,w.book])),base=new Set(PARTNERS.map(p=>p.id)),number=n=>Number.isFinite(n)&&n>=0?Math.min(Math.floor(n),1000000):0;
 const players=raw.players.map(p=>{if(!base.has(p.partner))throw Error('伙伴数据不正确');return{name:String(p.name||'训练家').slice(0,12),partner:p.partner,xp:Object.fromEntries(PARTNERS.map(b=>[b.id,number(p.xp?.[b.id])])),eeveeEvolution:EEVEE_FORMS.some(f=>f.id===p.eeveeEvolution)?p.eeveeEvolution:null,rewards:Object.fromEntries(PARTNERS.map(b=>[b.id,number(p.rewards?.[b.id])]))}});
 const records=raw.records.filter(r=>(ids.has(r.item)||ids.has(data.aliases?.[r.item]))&&[...STAGES,'listen'].includes(r.stage)&&['solo','gym','coop','relay'].includes(r.scope)&&[0,1].includes(r.player)&&['answer','heard','practice'].includes(r.type)).map(r=>({id:String(r.id).slice(0,100),at:Number.isFinite(r.at)&&r.at>=0?Math.min(r.at,10000000000000):0,book:r.book,item:r.item,stage:r.stage,scope:r.scope,player:r.player,session:String(r.session).slice(0,150),taskId:typeof r.taskId==='string'?r.taskId.slice(0,150):undefined,event:r.event==='letter'?'letter':'submit',round:number(r.round),type:r.type,correct:r.correct===null?null:r.correct===true,assisted:r.assisted===true}));
 const restored=migrate({version:raw.version,book:books.has(raw.book)?raw.book:'upper',players,records,rounds:Object.fromEntries([...books].map(b=>[b,number(raw.rounds?.[b])])),partners:Object.fromEntries(PARTNERS.map(b=>[b.id,number(raw.partners?.[b.id])])),badges:Object.fromEntries([...books].map(b=>[b,Array.isArray(raw.badges?.[b])?raw.badges[b].filter(s=>typeof s==='string').map(s=>s.slice(0,150)):[]])),settings:Object.fromEntries(['music','effects','reduced'].map(k=>[k,raw.settings?.[k]===true]))},data);
 return restored;
}
